const crypto = require('crypto');

const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};
const sigHeader = headers['x-retell-signature'] || headers['X-Retell-Signature'];
const apiKey = $env.RETELL_API_KEY;

const result = { ...body, verified: false, reason: null };

if (!sigHeader) {
  result.reason = 'missing signature header';
  return [{ json: result }];
}

// Retell's documented format is "v=<timestamp>,d=<digest>".
// VERIFY THE EXACT SIGNED STRING AGAINST RETELL'S CURRENT DOCS OR THEIR
// OFFICIAL SDK's verify() HELPER before relying on this in production —
// this reproduces the general HMAC-SHA256 + timestamp-window pattern
// their docs describe, but the precise byte string being signed
// (timestamp + '.' + rawBody below) should be confirmed against their
// reference implementation, not just this reconstruction.
const parts = Object.fromEntries(
  sigHeader.split(',').map(p => { const [k, v] = p.split('='); return [k, v]; })
);
const timestamp = parts.v;
const digest = parts.d;

if (!timestamp || !digest) {
  result.reason = 'malformed signature header';
  return [{ json: result }];
}

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - Number(timestamp)) > 300) {
  result.reason = 'stale timestamp (possible replay)';
  return [{ json: result }];
}

const rawBody = JSON.stringify(body);
const expected = crypto
  .createHmac('sha256', apiKey)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

let isValid = false;
try {
  isValid = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(digest));
} catch (e) {
  isValid = false; // length mismatch etc. — treat as invalid, not a crash
}

result.verified = isValid;
result.reason = isValid ? null : 'signature mismatch';
return [{ json: result }];

// Current Haiku 4.5 pricing (confirmed against Anthropic's pricing page,
// July 2026) — $1/$5 per million input/output tokens, cache reads at
// 10% of input price. Update these three constants if pricing changes;
// historical rows keep whatever cost was computed at the time, by design.
const INPUT_PRICE_PER_MTOK = 1.00;
const OUTPUT_PRICE_PER_MTOK = 5.00;
const CACHE_READ_PRICE_PER_MTOK = 0.10;

const response = $input.item.json;
const startedAtMs = $('Record Call Start Time').item.json._aiCallStartedAtMs;
const latencyMs = startedAtMs ? Date.now() - startedAtMs : null;
const usage = response.usage || {};
const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;
const cacheReadTokens = usage.cache_read_input_tokens || 0;

const costUsd =
  (inputTokens / 1_000_000) * INPUT_PRICE_PER_MTOK +
  (outputTokens / 1_000_000) * OUTPUT_PRICE_PER_MTOK +
  (cacheReadTokens / 1_000_000) * CACHE_READ_PRICE_PER_MTOK;

const usageMeta = {
  ai_model: response.model || 'claude-haiku-4-5-20251001',
  ai_input_tokens: inputTokens,
  ai_output_tokens: outputTokens,
  ai_cache_read_tokens: cacheReadTokens,
  ai_cost_usd: Number(costUsd.toFixed(6)),
  ai_latency_ms: latencyMs,
};

let parsed;
try {
  const text = response.content?.[0]?.text || '';
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { valid: false, reason: 'unparseable JSON from Claude', ...usageMeta } }];
}

const requiredFields = ['qualification', 'urgency', 'situation_summary', 'suggested_opening'];
const missing = requiredFields.filter((f) => parsed[f] === undefined);
const validQualification = ['qualified', 'not_qualified'].includes(parsed.qualification);
const validUrgency = ['low', 'medium', 'high', 'critical'].includes(parsed.urgency);

if (missing.length > 0 || !validQualification || !validUrgency) {
  return [{ json: {
    valid: false,
    reason: `schema validation failed: missing=${missing.join(',')}, qualification=${parsed.qualification}, urgency=${parsed.urgency}`,
    ...usageMeta,
  } }];
}

return [{ json: { valid: true, ...parsed, ...usageMeta } }];

const input = $json;
const status = input.valid === false ? 'failed' : 'no_brief';
return [{ json: {
  transcript_id: $('Insert Transcript').item.json[0].id,
  new_status: status,
  ai_model: input.ai_model,
  ai_input_tokens: input.ai_input_tokens,
  ai_output_tokens: input.ai_output_tokens,
  ai_cache_read_tokens: input.ai_cache_read_tokens,
  ai_cost_usd: input.ai_cost_usd,
  ai_latency_ms: input.ai_latency_ms,
} }];

const existing = $('Fetch Customer').item.json[0];
const ai = $json;
const patch = {};

const looksLikePlaceholder = existing.name && existing.name.startsWith('Caller ');
if ((looksLikePlaceholder || !existing.name) && ai.homeowner_name) {
  patch.name = ai.homeowner_name;
}
if (!existing.email && ai.homeowner_email) {
  patch.email = ai.homeowner_email;
}
if (!existing.property_address && ai.property_address) {
  patch.property_address = ai.property_address;
}

return [{ json: { customer_id: existing.id, patch, hasPatch: Object.keys(patch).length > 0 } }];

// Runs after the Twilio node whether it succeeded or failed
// (continueOnFail=true upstream). n8n surfaces a failed HTTP node's
// result with an `error` field rather than throwing when
// continueOnFail is set — check for that instead of assuming success.
const twilioResult = $json;
const smsSucceeded = !twilioResult.error && !!twilioResult.sid;

return [{ json: {
  notification_id: $('Insert Notification').item.json[0].id,
  channels_sent: smsSucceeded ? ['in_app', 'sms'] : ['in_app'],
} }];
